import React, { useEffect, useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import { getAllNetflix } from '../api/netflixApi';

const NetflixList = () => {
    const [movies, setMovies] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchNetflixMovies = async () => {
        try {
            const res = await getAllNetflix();
            setMovies(res.data);
        } catch (error) {
            console.error("Error al cargar películas de Netflix:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchNetflixMovies();
    }, []);

    return (
        <div className="container mt-4">
            <h2 className="mb-4 text-center">Películas de Netflix</h2>
            <div className="table-responsive shadow rounded">
                <table className="table table-striped table-hover table-bordered align-middle">
                    <thead className="table-dark">
                        <tr>
                            <th>Película</th>
                            <th>Descripción</th>
                            <th>Estado</th>
                        </tr>
                    </thead>
                    <tbody>
                        {loading ? (
                            <tr>
                                <td colSpan="3" className="text-center">Cargando...</td>
                            </tr>
                        ) : movies.length > 0 ? (
                            movies.map((movie) => (
                                <tr key={movie.code}>
                                    <td>{movie.name}</td>
                                    <td>{movie.description}</td>
                                    <td>
                                        <span className={`badge ${movie.status === 'A' ? 'bg-success' : 'bg-danger'}`}>
                                            {movie.status === 'A' ? 'Activo' : 'Inactivo'}
                                        </span>
                                    </td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan="3" className="text-center">No hay películas de Netflix disponibles</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default NetflixList;
